# qx2_base_n :: (255, 16)
def qx2_base_n(n, b):
    if n == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    out = ''
    while n:
        out = digits[n % b] + out
        n //= b
    return out

if __name__ == '__main__':
    print(qx2_base_n((255, 16)))

